void SwAutoCorrect::refreshBlockList( const uno::Reference< embed::XStorage >& rStg )
{
    if (rStg.is())
    {
        // mba: relative URLs don't make sense here
        m_pTextBlocks.reset( new SwXMLTextBlocks( rStg, OUString() ) );
